package dev.studyforge.banking.application; import dev.studyforge.banking.domain.*; import java.util.*; public final class DepositService{private final UnitOfWork uow;private final TransactionFactory factory;private final List<NotificationPort> notifications;public DepositService(UnitOfWork u,TransactionFactory f,List<NotificationPort> n){uow=u;factory=f;notifications=List.copyOf(n);}public Transaction deposit(Deposit c){Transaction tx=factory.deposit(c.accountId(),c.amount());Transaction done=uow.execute((a,t)->{Account old=a.findById(c.accountId()).orElseThrow(()->new AccountNotFoundException(c.accountId()));a.save(old.credit(c.amount()));t.save(tx);return tx;});for(NotificationPort n:notifications)try{n.transactionCompleted(done);}catch(RuntimeException e){throw new NotificationDeliveryException(done,e);}return done;}}
